from collections import Counter, deque

def components(grid, color):
    h,w=len(grid),len(grid[0]); seen=set(); comps=[]
    for i in range(h):
        for j in range(w):
            if grid[i][j]==color and (i,j) not in seen:
                q=deque([(i,j)]); seen.add((i,j)); comp=[]
                while q:
                    a,b=q.popleft(); comp.append((a,b))
                    for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                        x,y=a+da,b+db
                        if 0<=x<h and 0<=y<w and grid[x][y]==color and (x,y) not in seen:
                            seen.add((x,y)); q.append((x,y))
                comps.append(comp)
    return comps

def transform(grid):
    h,w=len(grid),len(grid[0])
    cnt=Counter(v for row in grid for v in row)
    bg=cnt.most_common(1)[0][0]
    others=[c for c in cnt if c!=bg]
    # anchor color = non-bg with more cells; dot color = fewer
    a_col,d_col=sorted(others,key=lambda c:-cnt[c])[:2] if len(others)>=2 else (others[0],None)
    out=[row[:] for row in grid]
    if d_col is None: return out
    anchors=[c for c in components(grid,a_col)]
    dots=[c[0] for c in components(grid,d_col)]
    # classify anchors: vertical (all same col) or horizontal (all same row)
    def orient(comp):
        rows={p[0] for p in comp}; cols={p[1] for p in comp}
        if len(cols)==1: return ('V',comp[0][1],min(rows),max(rows))
        return ('H',comp[0][0],min(cols),max(cols))
    an=[orient(c) for c in anchors]
    for (dr,dc) in dots:
        attached=None; mirror=None
        for A in an:
            if A[0]=='V' and A[2]<=dr<=A[3]: attached=A
            elif A[0]=='H' and A[2]<=dc<=A[3]: attached=A
        if attached is None: continue
        mirror=[A for A in an if A is not attached][0]
        if attached[0]=='V':
            _,ac,r0,r1=attached; off=dr-r0
            lo,hi=min(ac,dc),max(ac,dc)
            for j in range(lo,hi+1): out[dr][j]=d_col if j==dc else d_col
            out[dr][dc]=4
            # mirror fill full row
            if mirror[0]=='V':
                _,mc,m0,m1=mirror
                mr=m0+off
                for j in range(w):
                    if j!=mc: out[mr][j]=d_col
        else:
            _,ar,c0,c1=attached; off=dc-c0
            lo,hi=min(ar,dr),max(ar,dr)
            for i in range(lo,hi+1): out[i][dc]=d_col
            out[dr][dc]=4
            if mirror[0]=='H':
                _,mr,m0,m1=mirror
                mc=m0+off
                for i in range(h):
                    if i!=mr: out[i][mc]=d_col
    return out

